mapper.select:
SELECT v.id AS reference_id,0 AS reference_revision,'PREPARATION' AS target_kind,i.id AS target_id, v.id AS target_version_id,v.version_number AS target_version_number,NULL AS target_revision,i.status, i.current_version_id=v.id AS target_current,NULL AS anchor_item_id,NULL AS other_item_id,NULL AS anchor_version_id FROM preparation_material_reference s JOIN preparation_version v ON v.owner_id=s.owner_id AND v.item_id=s.item_id AND v.id=s.version_id JOIN preparation_item i ON i.owner_id=v.owner_id AND i.id=v.item_id WHERE s.owner_id=#{owner} AND s.excerpt_id=#{excerptId} AND s.version_id > #{afterId}
SELECT FROM ai_material_draft_source s JOIN ai_task t ON t.owner_id=s.owner_id AND t.id=s.task_id AND t.purpose='KNOWLEDGE_DRAFT' WHERE s.owner_id=#{owner} AND s.excerpt_id=#{excerptId}
SELECT FROM ai_material_draft_source s JOIN ai_task t ON t.owner_id=s.owner_id AND t.id=s.task_id AND t.purpose='QUESTION_DRAFT' WHERE s.owner_id=#{owner} AND s.excerpt_id=#{excerptId}
SELECT FROM ai_material_qa_source s JOIN ai_task t ON t.owner_id=s.owner_id AND t.id=s.task_id AND t.purpose='MATERIAL_QA' WHERE s.owner_id=#{owner} AND s.excerpt_id=#{excerptId}
SELECT FROM ai_fact_draft_material s JOIN ai_task t ON t.owner_id=s.owner_id AND t.id=s.task_id AND t.purpose='FACT_DRAFT' WHERE s.owner_id=#{owner} AND s.excerpt_id=#{excerptId} AND s.kind='MATERIAL'
SELECT FROM ai_relation_evidence_material s JOIN ai_task t ON t.owner_id=s.owner_id AND t.id=s.task_id AND t.purpose='RELATION_DRAFT' WHERE s.owner_id=#{owner} AND s.excerpt_id=#{excerptId} AND s.kind='MATERIAL'
SELECT FROM (SELECT DISTINCT task_id FROM ai_source_qa_source WHERE owner_id=#{owner} AND excerpt_id=#{excerptId} AND domain='MATERIAL_EXCERPT' AND task_id > #{afterId}) s JOIN ai_task t ON t.owner_id=#{owner} AND t.id=s.task_id AND t.purpose='SOURCE_QA'
SELECT e.id AS reference_id,0 AS reference_revision,'RELATION' AS target_kind,e.relation_id AS target_id, NULL AS target_version_id,NULL AS target_version_number,NULL AS target_revision, CASE WHEN r.id IS NULL THEN 'REMOVED' ELSE 'ACTIVE' END AS status,r.id IS NOT NULL AS target_current, e.source_id AS anchor_item_id,e.target_id AS other_item_id,NULL AS anchor_version_id FROM knowledge_relation_evidence_material s JOIN knowledge_relation_evidence e ON e.owner_id=s.owner_id AND e.id=s.evidence_id AND e.source_kind=s.source_kind LEFT JOIN knowledge_relation r ON r.owner_id=e.owner_id AND r.id=e.relation_id AND r.source_id=e.source_id AND r.target_id=e.target_id AND r.relation_type=e.relation_type WHERE s.owner_id=#{owner} AND s.excerpt_id=#{excerptId} AND s.source_kind='MATERIAL' AND s.evidence_id > #{afterId}
SELECT h.review_id AS reference_id,h.revision AS reference_revision,'STANDARD_REVIEW' AS target_kind, h.review_id AS target_id,NULL AS target_version_id,NULL AS target_version_number,h.revision AS target_revision, r.status,r.revision=h.revision AS target_current,h.question_id AS anchor_item_id,NULL AS other_item_id, h.question_version_id AS anchor_version_id FROM (SELECT DISTINCT review_id,revision FROM standard_review_evidence WHERE owner_id=#{owner} AND excerpt_id=#{excerptId} AND basis_kind='MATERIAL_EXCERPT'
AND (review_id > #{afterId} OR (review_id=#{afterId} AND revision > #{afterRevision})) ) s JOIN standard_review_revision h ON h.owner_id=#{owner} AND h.review_id=s.review_id AND h.revision=s.revision JOIN standard_review r ON r.owner_id=h.owner_id AND r.id=h.review_id AND r.question_id=h.question_id AND r.question_version_id=h.question_version_id
SELECT NULL AS reference_id,0 AS reference_revision,'AI_TASK' AS target_kind,NULL AS target_id, NULL AS target_version_id,NULL AS target_version_number,NULL AS target_revision,NULL AS status, FALSE AS target_current,NULL AS anchor_item_id,NULL AS other_item_id,NULL AS anchor_version_id WHERE 1=0
ORDER BY reference_id,reference_revision LIMIT #{limit}
